L["Icon"] = "Иконка"
-- en: "Item icons"
L["Item icons"] = "Иконки предметов"
-- en: "Known spells"
L["Known spells"] = "Известные заклинания"
-- en: "Manage conditions"
L["Manage conditions"] = "Управление условиями"
-- en: "Next"
L["Next"] = "Далее"
